SCRIPT = r'''<script>
(() => {
  const notes = {
    led: ['LED/LCD', 'An LCD pixel layer controls the picture while an LED backlight supplies the light. Affordable, bright and widely available; black levels depend on the backlight and local dimming.', 'Best for: budget, bedroom, general family viewing.', 'Light path: LED backlight → LCD shutter → colour filters → your eyes.'],
    qled: ['QLED', 'A conventional LCD/LED TV adds a quantum-dot layer. The dots convert backlight energy into more controlled colours and can help brightness and colour volume.', 'Best for: bright rooms, sports and colourful content.', 'Light path: LED backlight → quantum dots tune colour → LCD shutter → screen.'],
    miniled: ['Mini LED', 'Still LCD-based, but the backlight uses many smaller LEDs and local-dimming zones. More zones can improve contrast, though halos can still appear around bright objects.', 'Best for: bright living rooms, HDR and large screens.', 'Light path: many small LED zones dim independently → LCD shutter → screen.'],
    oled: ['OLED', 'Each pixel emits its own light and can switch completely off. That produces very deep blacks, precise contrast and wide viewing angles; static logos can create retention risk over time.', 'Best for: movies, dark-room viewing and premium contrast.', 'Light path: electrical current → self-lit organic pixel → your eyes; no backlight.'],
    qned: ['QNED / premium LCD', 'A brand category for advanced LCD TVs that may combine quantum-dot or colour layers with sophisticated backlighting. Check the exact model because the ingredients vary.', 'Best for: bright rooms when you want premium LCD brightness.', 'Light path: premium LCD stack; exact colour layer and backlight vary by model.']
  };
  const render = key => { const n=notes[key]; document.querySelector('#techName').textContent=n[0]; document.querySelector('#techHow').textContent=n[1]; document.querySelector('#techUse').textContent=n[2]; document.querySelector('#labFlow').textContent=n[3]; document.querySelector('#techLab').dataset.tech=key; document.querySelectorAll('.tech-switch button').forEach(b=>b.setAttribute('aria-pressed', b.dataset.tech===key?'true':'false')); };
  document.querySelectorAll('.tech-switch button').forEach(b=>b.addEventListener('click',()=>render(b.dataset.tech)));
  const choices = {
    size: '<strong>Start with size</strong><br>Bedroom: usually 32–50″ · Living room: usually 43–65″ · Hall: usually 65–98″. Confirm the exact wall and sofa distance in the <a href="/tvs/tv-size-calculator/">3D calculator</a>.',
    tech: '<strong>Then choose technology</strong><br>Bright room/HDR: Mini LED or QLED. Movies/dark room: OLED. Budget/general viewing: LED/LCD. QNED is a premium LCD category—check the exact model.',
    use: '<strong>Best today depends on use</strong><br>There is no single universal winner. OLED leads on pixel-level black; Mini LED leads on bright-room punch; QLED is a strong colour/brightness value option; LED/LCD wins on budget.'
  };
  const choicePanel = document.querySelector('#choicePanel');
  document.querySelectorAll('.choice-tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.choice-tabs button').forEach(x=>x.setAttribute('aria-selected',x===b?'true':'false')); choicePanel.innerHTML=choices[b.dataset.choice];}));
  choicePanel.innerHTML=choices.size;
  render('miniled');
})();
</script>'''


def publish(destination: Path):
    body = f'''<article class="tvguide"><p class="eyebrow">TV knowledge portal · India</p><h1>How to choose your TV for bedroom, living room or hall</h1><p>Start with the room, viewing distance and wall—not the brand name. Then choose the display technology that matches your light, content and budget.</p>{STYLE}<div class="tvguide-layout"><main class="tvguide-main"><section><h2>1. Choose the size first</h2><p>Use our interactive calculator to enter viewing distance, wall width and room size. Press Enter to see the calculation breakdown, TV-size badge and 3D room view.</p><div class="size-grid"><div class="size-card"><strong>Bedroom</strong><span>Usually 32–50″. Measure from pillow/bed eye position; avoid a screen that dominates a short viewing distance.</span></div><div class="size-card"><strong>Living room</strong><span>Usually 43–65″. Choose using the normal sofa-to-screen distance and leave wall clearance for speakers and ventilation.</span></div><div class="size-card"><strong>Hall / large room</strong><span>Usually 65–98″. Check wall width, viewing angle, delivery access, mount strength and sofa layout.</span></div></div></section><section class="tech-visual"><div class="layer-stack" aria-label="Illustrative 3D display layer diagram"><div class="layer"></div><div class="layer"></div><div class="layer"></div><div class="layer"></div><div class="layer"></div></div><div><h2>What happens behind the picture?</h2><p>Most TVs are a stack of optical layers: light source, colour/filter layers, pixel control and protective glass. OLED creates light at pixel level; LED, QLED, QNED and Mini LED use an LCD picture layer with a backlight.</p><p class="muted">This is an explanatory engineering illustration, not a teardown of one exact model.</p></div></section><section><h2>2. Choose the TV technology</h2><div class="tech-switch" role="tablist"><button type="button" data-tech="led" aria-pressed="false">LED/LCD</button><button type="button" data-tech="qled" aria-pressed="false">QLED</button><button type="button" data-tech="miniled" aria-pressed="false">Mini LED</button><button type="button" data-tech="oled" aria-pressed="false">OLED</button><button type="button" data-tech="qned" aria-pressed="false">QNED</button></div><div class="tech-card tech-note"><strong id="techName">Mini LED</strong><p id="techHow"></p><p id="techUse" class="use"></p></div><table><thead><tr><th>Type</th><th>Picture strength</th><th>Trade-off</th></tr></thead><tbody><tr><td>LED/LCD</td><td>Good brightness and value</td><td>Black level and halo depend on backlight design</td></tr><tr><td>QLED</td><td>Bright, saturated colour</td><td>Still relies on LCD/backlight; model quality varies</td></tr><tr><td>Mini LED</td><td>High brightness with better local contrast</td><td>May show blooming/halo; more expensive</td></tr><tr><td>OLED</td><td>Pixel-level black and contrast</td><td>Static-content retention risk; brightness varies by model/room</td></tr><tr><td>QNED</td><td>Premium LCD colour/brightness options</td><td>Brand category; check exact backlight and dimming spec</td></tr></tbody></table></section><section><h2>3. Which is kinder to the eyes?</h2><div class="eye-box"><p><strong>No TV technology is automatically eye-safe.</strong> Eye comfort depends more on brightness, glare, flicker, viewing distance, room lighting, text size and breaks. Pick a TV with comfortable brightness control, avoid watching in a pitch-dark room, reduce reflections and keep the screen at a comfortable angle.</p><p>Use the 20-20-20 habit: every 20 minutes, look at something about 20 feet away for at least 20 seconds. Blink normally; wash your face if you like, but washing the eyes is not the main treatment for screen strain. Persistent pain, blurred vision, headaches or dryness should be checked by an eye professional.</p></div></section><section><h2>4. How long can you watch?</h2><div class="warning-box"><ul><li>There is no universal “safe number of TV hours” for every adult; take regular breaks instead of watching continuously.</li><li>For children, follow age-appropriate family limits and protect sleep, outdoor activity and homework time.</li><li>Lower brightness to match the room, use a warm/comfort mode at night, and avoid direct glare behind the sofa.</li><li>Do not claim that OLED, QLED or Mini LED alone prevents eye strain—the viewing setup matters more.</li></ul></div></section><section><h2>Use the 3D distance calculator</h2><p>Enter your room data, press Enter, then switch to Top view and rotate the room through 360°. The recommended size appears on the TV model and in the calculation summary.</p><p><a href="/tvs/tv-size-calculator/">Open the interactive TV-size calculator →</a></p></section><section><h2>Sources and engineering notes</h2><ul class="source-list"><li><a href="https://www.lg.com/in/magazine/oled-vs-qned-vs-mini-led/" rel="noopener noreferrer nofollow">LG India: OLED vs QNED vs Mini LED</a> — display mechanism comparison.</li><li><a href="https://www.samsung.com/in/tvs/tv-buying-guide/what-is-qled-oled-and-neo-qled/" rel="noopener noreferrer nofollow">Samsung India: QLED, OLED and Neo QLED</a> — quantum-dot explanation.</li><li><a href="https://www.aao.org/eye-health/treatments/computer-usage" rel="noopener noreferrer nofollow">American Academy of Ophthalmology: digital devices and eye strain</a> — comfort guidance.</li><li><a href="https://www.aoa.org/healthy-eyes/eye-and-vision-conditions/computer-vision-syndrome" rel="noopener noreferrer nofollow">American Optometric Association: computer vision syndrome</a> — 20-20-20 rule.</li></ul><p class="disclaimer">This page provides general buying and viewing-comfort information, not medical diagnosis. TV specifications and technology names vary by exact model.</p></section></main><aside class="tvguide-side"><h2>TV decision shortcut</h2><p><strong>First:</strong> measure sofa-to-screen distance.</p><p><strong>Then:</strong> check wall width and room light.</p><p><strong>Finally:</strong> choose panel type and features.</p><a href="/tvs/tv-size-calculator/">Open 3D size calculator</a><a href="/tvs/india-20/">Compare India-market TVs</a><p class="muted">Tip: a larger TV is not automatically better if the viewing distance is short.</p></aside></div></article>'''
    hero_markup = '<section class="world-hero"><div class="world-copy"><p class="eyebrow">TV Discovery Lab · India</p><h1>Choose a TV that feels <em>made for your room.</em></h1><p class="hero-lead">See the science, feel the difference, and decide with confidence. Size, light, technology and comfort—one guided experience.</p><div class="hero-triad"><span><i></i>Room-aware sizing</span><span><i></i>Display science</span><span><i></i>Eye-comfort habits</span></div></div><div class="hero-stage" aria-label="Decorative 3D television illustration"><div class="hero-orbit"></div><div class="hero-floor"></div><div class="hero-ray"></div><div class="hero-tv"><div class="hero-screen"></div></div><div class="hero-chip"><strong>360°</strong>explore your choice</div></div></section><div class="world-strap"><span><b>01</b> Find the right size</span><span><b>02</b> Decode the panel</span><span><b>03</b> Match your room</span></div>'
    choice_markup = '<section class="choice-flow"><h2>Before you buy: make the decision in 3 clicks</h2><div class="choice-tabs" role="tablist"><button type="button" data-choice="size" aria-selected="true">1 · Television size</button><button type="button" data-choice="tech" aria-selected="false">2 · Technology</button><button type="button" data-choice="use" aria-selected="false">3 · Best for your room</button></div><div id="choicePanel" class="choice-panel" aria-live="polite"></div></section>'
    lab_markup = '<div id="techLab" class="tech-lab" data-tech="miniled"><div class="lab-stage"><div class="lab-beam"></div><div class="lab-tv"><div class="lab-screen"><div class="lab-dots">' + ''.join('<span></span>' for _ in range(32)) + '</div></div><div class="lab-backlight"></div></div><div class="lab-callout">Light path is simplified for learning</div></div><div class="lab-copy"><h3>Science view: <span id="labFlow">many small LED zones dim independently → LCD shutter → screen.</span></h3><p>Think of the screen as a controlled light system. The visual changes with the tab: backlight layers for LED/QLED/Mini LED, or self-lit pixels for OLED.</p><div class="lab-legend"><span class="zone">Backlight / zones</span><span class="quantum">Quantum-dot colour</span><span class="self">Self-lit pixels</span></div></div></div>'
    body = body.replace('<p class="eyebrow">TV knowledge portal · India</p><h1>How to choose your TV for bedroom, living room or hall</h1><p>Start with the room, viewing distance and wall—not the brand name. Then choose the display technology that matches your light, content and budget.</p>', hero_markup, 1)
    body = body.replace(STYLE + '<div class="tvguide-layout"', WORLD_STYLE + STYLE + LAB_STYLE + choice_markup + '<div class="tvguide-layout"', 1)
    body = body.replace('<div class="tech-card tech-note">', lab_markup + '<div class="tech-card tech-note">', 1)
    route_dir = destination / "tvs" / "how-to-choose"
    route_dir.mkdir(parents=True, exist_ok=True)
    html = doc("How to Choose a TV for Bedroom, Living Room or Hall", "A practical India TV buying guide covering room size, viewing distance, LED, QLED, Mini LED, OLED, QNED and eye-comfort habits.", ROUTE, body, schema("How to Choose a TV", ROUTE, "tvs"))
    (route_dir / "index.html").write_text(html.replace("</body>", SCRIPT + "</body>"), encoding="utf-8")
    hub = destination / "tvs" / "index.html"
    if hub.exists():
        hub_html = hub.read_text(encoding="utf-8")
        link = '''<section class="cr-guidance tv-tools-guides"><h2>TV Tools &amp; Guides</h2><p>Start here to choose the right TV, understand display technology and compare India-market models.</p><div class="tv-tools-grid"><a href="/tvs/tv-size-calculator/"><strong>3D TV Size Calculator</strong><span>Enter room size and viewing distance; see the recommended size and rotate the room view.</span></a><a href="/tvs/how-to-choose/"><strong>How to Choose Your TV</strong><span>Bedroom, living room and hall sizing, LED/QLED/OLED/Mini LED guide and eye-comfort tips.</span></a><a href="/tvs/india-20/"><strong>India TV Comparison</strong><span>Source-linked India-market TV research with technical notes and retailer references.</span></a></div></section><style>.tv-tools-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}.tv-tools-grid a{display:block;padding:15px;border:1px solid #dbe3ef;border-radius:14px;background:#f8fafc;color:inherit;text-decoration:none}.tv-tools-grid a:hover{border-color:#0ea5e9;background:#eff6ff}.tv-tools-grid strong,.tv-tools-grid span{display:block}.tv-tools-grid strong{color:#075985;margin-bottom:6px}.tv-tools-grid span{font-size:13px}@media(max-width:760px){.tv-tools-grid{grid-template-columns:1fr}}</style>'''
        feature = '''<section class="tv-discovery-feature"><div><p class="tv-discovery-kicker">TV DISCOVERY LAB · NEW</p><h2>Choose your TV like a pro.</h2><p>See the room, size and display science together before you buy. Explore the interactive 3D guide and understand what is happening behind the picture.</p><div class="tv-discovery-actions"><a href="/tvs/how-to-choose/">Open the TV Discovery Lab →</a><span>Size · Technology · Comfort</span></div></div><div class="tv-discovery-stage" aria-label="Decorative 3D television illustration"><div class="tv-discovery-orbit"></div><div class="tv-discovery-screen"><span>TV LAB</span></div><div class="tv-discovery-glow"></div></div><style>.tv-discovery-feature{position:relative;display:grid;grid-template-columns:1.08fr .92fr;gap:22px;align-items:center;margin:0 0 22px;padding:clamp(24px,4vw,42px);border-radius:24px;overflow:hidden;color:#effaff;background:radial-gradient(circle at 80% 20%,#22d3ee55 0 4%,transparent 25%),linear-gradient(135deg,#07152d,#102a56 58%,#075985);box-shadow:0 20px 48px #0f4c8130}.tv-discovery-feature:after{content:"";position:absolute;right:-100px;bottom:-170px;width:360px;height:360px;border:1px solid #67e8f955;border-radius:50%;box-shadow:0 0 0 24px #67e8f20d,0 0 0 52px #67e8f20a;pointer-events:none}.tv-discovery-kicker{margin:0 0 10px;color:#a5f3fc;font-size:11px;font-weight:900;letter-spacing:.15em}.tv-discovery-feature h2{margin:0;color:#fff;font-size:clamp(28px,4vw,48px);line-height:1.04;letter-spacing:-.04em}.tv-discovery-feature p:not(.tv-discovery-kicker){max-width:570px;margin:14px 0 0;color:#dbeafe;line-height:1.6}.tv-discovery-actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:22px}.tv-discovery-actions a{padding:12px 16px;border-radius:12px;background:#67e8f9;color:#082f49;text-decoration:none;font-weight:900;box-shadow:0 9px 20px #02061744}.tv-discovery-actions span{color:#bae6fd;font-size:13px;font-weight:800}.tv-discovery-stage{position:relative;min-height:210px;perspective:900px}.tv-discovery-screen{position:absolute;left:8%;right:5%;top:17%;height:58%;padding:8px;border:2px solid #93c5fd66;border-radius:11px;background:linear-gradient(145deg,#0b1220,#020617);transform:rotateY(-17deg) rotateX(7deg);box-shadow:18px 24px 0 #02061755,0 20px 45px #0009,0 0 30px #22d3ee66;overflow:hidden}.tv-discovery-screen:before{content:"";position:absolute;inset:8px;border-radius:5px;background:radial-gradient(circle at 68% 35%,#fef08a 0 3%,transparent 15%),linear-gradient(135deg,#020617,#312e81 48%,#0891b2)}.tv-discovery-screen span{position:absolute;left:16px;bottom:13px;color:#ecfeff;font-size:12px;font-weight:900;letter-spacing:.18em}.tv-discovery-orbit{position:absolute;inset:2% 0;border:1px solid #67e8f955;border-radius:50%;transform:rotateX(63deg) rotateZ(-10deg);animation:tvDiscoverySpin 13s linear infinite}.tv-discovery-glow{position:absolute;left:14%;right:6%;bottom:7%;height:35px;border-radius:50%;background:#22d3ee66;filter:blur(18px)}@keyframes tvDiscoverySpin{to{transform:rotateX(63deg) rotateZ(350deg)}}@media(prefers-reduced-motion:reduce){.tv-discovery-orbit{animation:none}}@media(max-width:760px){.tv-discovery-feature{grid-template-columns:1fr}.tv-discovery-stage{min-height:190px;order:-1}}</style></section>'''
        if "TV Tools &amp; Guides" not in hub_html:
            hub_html = hub_html.replace("</main>", feature + link + "</main>", 1)
        elif "tv-discovery-feature" not in hub_html:
            hub_html = hub_html.replace('<section class="cr-guidance tv-tools-guides">', feature + '<section class="cr-guidance tv-tools-guides">', 1)
        hub.write_text(hub_html, encoding="utf-8")
    ns="http://www.sitemaps.org/schemas/sitemap/0.9"; sitemap=destination/"sitemap.xml"; tree=ET.parse(sitemap); root=tree.getroot(); url=SITE+ROUTE
    existing={str(e.text) for e in root.findall(f"{{{ns}}}url/{{{ns}}}loc")}
    if url not in existing:
        node=ET.SubElement(root,f"{{{ns}}}url"); ET.SubElement(node,f"{{{ns}}}loc").text=url; tree.write(sitemap,encoding="utf-8",xml_declaration=True)
    print("Published TV knowledge portal", url)
    return [url]

